  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class Category {
  + CategoryName : string
}

City "1" -- "0..*" H2SLocation
H2SLocation "1" -- "0..*" DistributionCenter
H2SLocation "1" -- "0..*" PickupRequest
Resident "1" -- "0..*" PickupRequest
PickupRequest "1" -- "1..*" ScheduledItem
Vehicle "1" -- "0..*" PickupRoute
VolunteerDriver "1" -- "0..*" PickupRoute
PickupRoute "1" -- "1..*" ScheduledItem
ScheduledItem "1" -- "0..1" Article
ScheduledItem "1" -- "0..1" FoodItem
DistributionCenter "1" -- "*" Article
DistributionCenter "1" -- "*" FoodItem
H2SEmployee "1" -- "*" Article : inspects
H2SEmployee "1" -- "*" Client : calls
H2SEmployee "1" -- "*" Article : assignsCategory
Category "1" -- "*" Article
Client "0..*" -- "1" DistributionCenter : requestsDelivery
VolunteerDriver "1" -- "*" Client : delivers
Article "1" -- "0..*" Client : deliveredTo

@enduml

